enum ConflictStatus { none, localWins, remoteWins, needsResolution }
enum SyncItemStatus { pending, syncing, failed, completed }
class LocalChange { const LocalChange({required this.entityType,required this.entityId,required this.operation,required this.payload,required this.createdAt});final String entityType,entityId,operation;final Map<String,Object?> payload;final DateTime createdAt; }
class SyncQueueItem { const SyncQueueItem({required this.id,required this.change,this.status=SyncItemStatus.pending,this.retryCount=0,this.lastError});final String id;final LocalChange change;final SyncItemStatus status;final int retryCount;final String? lastError;SyncQueueItem copyWith({SyncItemStatus? status,int? retryCount,String? lastError})=>SyncQueueItem(id:id,change:change,status:status??this.status,retryCount:retryCount??this.retryCount,lastError:lastError);}
class SyncStatus { const SyncStatus({this.pendingCount=0,this.failedCount=0,this.isSyncing=false,this.lastSyncedAt,this.conflictStatus=ConflictStatus.none});final int pendingCount,failedCount;final bool isSyncing;final DateTime? lastSyncedAt;final ConflictStatus conflictStatus;}
abstract interface class SyncService { SyncStatus get status; List<SyncQueueItem> get queue; Future<void> enqueue(LocalChange change); Future<SyncStatus> sync(); }
class MockSyncService implements SyncService {final List<SyncQueueItem> _queue=[];DateTime? _last;@override List<SyncQueueItem> get queue=>List.unmodifiable(_queue);@override SyncStatus get status=>SyncStatus(pendingCount:_queue.where((e)=>e.status==SyncItemStatus.pending).length,failedCount:_queue.where((e)=>e.status==SyncItemStatus.failed).length,lastSyncedAt:_last);@override Future<void> enqueue(LocalChange c)async=>_queue.add(SyncQueueItem(id:'sync-${_queue.length}',change:c));@override Future<SyncStatus> sync()async{for(var i=0;i<_queue.length;i++){_queue[i]=_queue[i].copyWith(status:SyncItemStatus.completed);} _last=DateTime.now();return status;}}
